/**
 * Where the asset list comes from.
 *
 * `tokens.json` is a snapshot: it is generated by `exportStellarTrustlines` in
 * the backend and only changes when someone republishes it. The LI.FI token API
 * is the same list, live — so it is asked first, and the snapshot is the backup
 * for when the API cannot answer.
 *
 * The API describes a Stellar token by its Soroban C-address; a trustline needs
 * the classic `CODE:ISSUER` pair. That mapping lives on-chain, in the Stellar
 * Asset Contract's instance storage, so the page resolves it the same way the
 * export script does — including re-deriving the C-address from the pair it
 * decoded, since a wrong pair would have a partner trust the wrong asset.
 */

/** LI.FI chain id for Stellar mainnet. */
const STELLAR_CHAIN_ID = 1201081091099710

/**
 * Asked by chain *type* rather than by chain id: `STL` is already a valid value
 * and answers with an empty list until the chain goes live, where an id the API
 * does not know yet is a 400. The id then filters the answer down to mainnet.
 */
const TOKENS_URL = 'https://li.quest/v1/tokens?chainTypes=STL'

const TOKENS_TIMEOUT_MS = 8000

const MANIFEST_URL = './tokens.json'

/** `AUTH_REQUIRED_FLAG` on `AccountEntry.flags` (stellar-core `AccountFlags`). */
const AUTH_REQUIRED_FLAG = 1

/**
 * Why a token carries no trustline. `native` and `custom-token` are expected —
 * neither has a trustline concept — so they are counted but not complained
 * about; anything else means a token we may be sent is missing from the list.
 */
const BENIGN_SKIPS = new Set(['native', 'custom-token'])

// ------------------------------------------------------- The LI.FI API

/**
 * The live Stellar token list, priced only: an unpriced token cannot be quoted,
 * so it never becomes a route's input and no fee is ever collected in it. That
 * makes its trustline pure reserve cost. This mirrors the manifest's own rule.
 */
async function fetchApiTokens() {
  const response = await fetch(TOKENS_URL, {
    signal: AbortSignal.timeout(TOKENS_TIMEOUT_MS),
  })
  if (!response.ok) throw new Error(`HTTP ${response.status}`)
  const body = await response.json()
  const tokens = Object.values(body.tokens ?? {}).flat()
  return tokens.filter(
    (token) =>
      token.chainId === STELLAR_CHAIN_ID && Number(token.priceUSD) > 0
  )
}

// -------------------------------------------- C-address → CODE:ISSUER

/** The token list is keyed by address, so a repeat is the same asset twice. */
const unique = (tokens) => [
  ...new Map(tokens.map((token) => [token.address, token])).values(),
]

/**
 * Names an instance-storage key. The SAC writes unit enum variants as a
 * one-element vec of symbols (`AssetInfo`, `Admin`) but other contracts use a
 * bare symbol, so both shapes are handled.
 */
function storageKeyName(key) {
  switch (key.switch().name) {
    case 'scvSymbol':
      return key.sym().toString()
    case 'scvVec':
      return key.vec()?.[0]?.sym().toString() ?? null
    default:
      return null
  }
}

/**
 * Decodes an `AssetInfo` value into its classic asset, or `null` for the native
 * variant. `asset_code` is stored as the fixed-width classic asset code
 * (`AssetCode4`/`AssetCode12`), so trailing NUL padding is stripped — a 3-char
 * code like `EUR` arrives as `EUR\0`.
 */
function decodeAssetInfo(value) {
  const variant = value.vec()?.[0]?.sym().toString()
  if (variant === 'Native') return null
  if (variant !== 'AlphaNum4' && variant !== 'AlphaNum12') {
    throw new Error(`Unknown AssetInfo variant: ${variant}`)
  }

  const fields = new Map(
    (value.vec()?.[1]?.map() ?? []).map((entry) => [
      entry.key().sym().toString(),
      entry.val(),
    ])
  )
  const code = fields.get('asset_code')
  const issuer = fields.get('issuer')
  if (code === undefined || issuer === undefined) {
    throw new Error(`AssetInfo ${variant} is missing asset_code or issuer`)
  }
  return {
    code: code.str().toString().replace(/\0+$/, ''),
    issuer: StrKey.encodeEd25519PublicKey(issuer.bytes()),
  }
}

/**
 * Resolves one C-address to its classic asset, or a skip reason when no
 * trustline applies. A decode that cannot be trusted is a skip rather than a
 * failure: dropping an asset costs a partner one trustline they can add later,
 * where offering a wrong one has them trust an asset we never send.
 */
function resolveAsset(contract, data) {
  if (data === undefined) return 'instance-missing'

  const instance = data.contractData().val().instance()
  if (instance.executable().switch().name !== 'contractExecutableStellarAsset') {
    return 'custom-token'
  }

  const assetInfo = (instance.storage() ?? []).find(
    (entry) => storageKeyName(entry.key()) === 'AssetInfo'
  )
  if (assetInfo === undefined) return 'no-asset-info'

  let asset
  try {
    asset = decodeAssetInfo(assetInfo.val())
  } catch (error) {
    console.warn(`[tokens] ${contract}: ${error.message}`)
    return 'undecodable'
  }
  if (asset === null) return 'native'

  // The SAC address is a deterministic hash of the asset, so re-deriving it is
  // a total check on the decode above — including the NUL trimming.
  const derived = new Asset(asset.code, asset.issuer).contractId(
    NETWORK_PASSPHRASE
  )
  if (derived !== contract) {
    console.warn(
      `[tokens] ${contract} resolved to ${asset.code}:${asset.issuer}, which derives ${derived}`
    )
    return 'mismatch'
  }
  return asset
}

/** Resolves every token's C-address in one round-trip, plus the skip tally. */
async function resolveAssets(tokens) {
  const skipped = {}
  const skip = (reason) => {
    skipped[reason] = (skipped[reason] ?? 0) + 1
  }

  // One unreadable address must not cost the whole list, so the ledger key is
  // built per token: an address that is not a contract id at all is a skip.
  const keyByContract = new Map()
  for (const token of unique(tokens)) {
    try {
      keyByContract.set(
        token.address,
        new Contract(token.address).getFootprint().toXDR('base64')
      )
    } catch {
      skip('bad-address')
    }
  }
  const instances = await readLedgerEntries([...keyByContract.values()])

  const resolved = []
  for (const token of unique(tokens)) {
    const key = keyByContract.get(token.address)
    if (key === undefined) continue
    const outcome = resolveAsset(token.address, instances.get(key))
    if (typeof outcome === 'string') skip(outcome)
    else {
      resolved.push({ ...outcome, contract: token.address, symbol: token.symbol })
    }
  }
  return { resolved, skipped }
}

/**
 * Reads `AUTH_REQUIRED` for each issuer. Such an asset needs the issuer to
 * authorize the trustline before a transfer succeeds, so a partner has to know
 * the trustline alone is not enough. Issuers are shared across assets, so the
 * set is deduplicated before the lookup.
 */
async function readAuthRequired(issuers) {
  const keyByIssuer = new Map(
    issuers.map((issuer) => [issuer, accountLedgerKey(issuer)])
  )
  const entries = await readLedgerEntries([...keyByIssuer.values()])

  const authRequired = new Map()
  for (const [issuer, key] of keyByIssuer) {
    const data = entries.get(key)
    // A missing issuer account means the trustline cannot be created at all;
    // treating it as gated is the cautious read of an asset we cannot check.
    authRequired.set(
      issuer,
      data === undefined || (data.account().flags() & AUTH_REQUIRED_FLAG) !== 0
    )
  }
  return authRequired
}

/** Builds a manifest from the API, in the shape `tokens.json` publishes. */
async function buildApiManifest() {
  const tokens = await fetchApiTokens()
  if (tokens.length === 0) throw new Error('no Stellar tokens listed yet')

  const { resolved, skipped } = await resolveAssets(tokens)
  if (resolved.length === 0) throw new Error('no token resolved to a trustline')

  const authRequired = await readAuthRequired([
    ...new Set(resolved.map((asset) => asset.issuer)),
  ])

  const assets = resolved
    .map((asset) => ({
      code: asset.code,
      issuer: asset.issuer,
      contract: asset.contract,
      symbol: asset.symbol,
      authRequired: authRequired.get(asset.issuer),
    }))
    .sort(
      (a, b) => a.code.localeCompare(b.code) || a.issuer.localeCompare(b.issuer)
    )

  const unexpected = Object.entries(skipped).filter(
    ([reason]) => !BENIGN_SKIPS.has(reason)
  )
  if (unexpected.length > 0) {
    console.warn(
      `[tokens] ${unexpected.map(([reason, count]) => `${count} ${reason}`).join(', ')}`
    )
  }

  return {
    schemaVersion: 1,
    network: 'public',
    generatedAt: new Date().toISOString(),
    assets,
    source: 'api',
    skipped: Object.fromEntries(unexpected),
  }
}

// -------------------------------------------------- The published JSON

async function fetchManifest() {
  const response = await fetch(MANIFEST_URL)
  if (!response.ok) throw new Error(`HTTP ${response.status}`)
  const manifest = await response.json()
  if (manifest.network !== 'public') {
    throw new Error(`manifest is for ${manifest.network}, not mainnet`)
  }
  return { ...manifest, source: 'manifest', skipped: {} }
}

/**
 * The live list if it can be had, the published snapshot otherwise. Both are
 * the same data by construction, so falling back costs only freshness — and
 * the page says which one it is showing.
 */
async function loadManifest() {
  try {
    return await buildApiManifest()
  } catch (error) {
    console.info(`[tokens] falling back to tokens.json: ${error.message}`)
    try {
      return await fetchManifest()
    } catch (fallbackError) {
      throw new Error(
        `Could not load the token list. The LI.FI API said "${error.message}" and tokens.json said "${fallbackError.message}".`
      )
    }
  }
}
